// Verifies the HMAC signature over "<timestamp>.<raw body>" and validates the payload.
// Fails closed: a missing raw body, a stale timestamp or a bad signature returns 401.
const crypto = require('crypto');
const SECRET = $env.BTC_SCHEDULER_SIGNING_SECRET;
const WINDOW_SECONDS = 300;
const item = $input.first();
const reject = (httpCode, error, retryable = false) => [{ json: {
  ok: false, httpCode, response: { status: 'error', leadId: null, error, retryable, problems: [] }
} }];

if (!SECRET) return reject(503, 'signing secret not configured', true);

const h = item.json.headers || {};
const ts = String(h['x-btc-timestamp'] || '');
const sig = String(h['x-btc-signature'] || '');

let raw = null;
try {
  if (item.binary && item.binary.data) {
    raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
  }
} catch (e) {
  raw = null;
}
if (raw === null) return reject(401, 'unauthorized');

const now = Math.floor(Date.now() / 1000);
if (!/^\d{9,11}$/.test(ts) || Math.abs(now - Number(ts)) > WINDOW_SECONDS) return reject(401, 'unauthorized');
const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', SECRET).update(ts + '.' + raw, 'utf8').digest('hex'));
const given = Buffer.from(sig);
if (expected.length !== given.length || !crypto.timingSafeEqual(expected, given)) return reject(401, 'unauthorized');

let p;
try { p = JSON.parse(raw); } catch (e) { return reject(422, 'invalid JSON body'); }

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const FIELD = /^[A-Za-z][A-Za-z0-9_]*(__c)?$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MODES = ['create', 'match_or_create', 'update_only'];
const sfId = (v, prefixes) => typeof v === 'string' && /^[A-Za-z0-9]{15}([A-Za-z0-9]{3})?$/.test(v) && prefixes.some(x => v.startsWith(x));
const optText = (v, max) => v === undefined || v === null || (typeof v === 'string' && v.length <= max);
const problems = [];
if (!p || typeof p !== 'object') problems.push('body');
else {
  if (p.source !== 'btc-scheduler') problems.push('source');
  if (!UUID.test(String(p.bookingId || ''))) problems.push('bookingId');
  if (p.idempotencyKey !== p.bookingId) problems.push('idempotencyKey');
  if (String(h['idempotency-key'] || '') !== String(p.bookingId)) problems.push('Idempotency-Key header');
  const lead = p.lead;
  if (!lead || typeof lead !== 'object' || Array.isArray(lead)) problems.push('lead');
  else {
    for (const [k, v] of Object.entries(lead)) {
      if (!FIELD.test(k) || ['id', 'ownerid'].includes(k.toLowerCase())) problems.push('lead.' + k);
      if (v !== null && !['string', 'number', 'boolean'].includes(typeof v)) problems.push('lead.' + k);
    }
    if (!String(lead.LastName || '').trim()) problems.push('lead.LastName');
    if (!String(lead.Company || '').trim()) problems.push('lead.Company');
  }
  const o = p.owner || {};
  if (o.mode === 'assigned_host') {
    if (!/^[^\s@\\]+@[^\s@'\\]+\.[^\s@'\\]+$/.test(String(o.ownerEmail || ''))) problems.push('owner.ownerEmail');
  } else if (o.mode === 'fixed') {
    if (!sfId(o.ownerId, ['005', '00G'])) problems.push('owner.ownerId');
  } else if (o.mode !== 'assignment_rules') problems.push('owner.mode');
  if (typeof p.autoAssign !== 'boolean') problems.push('autoAssign');
  if (p.campaignId != null && !sfId(p.campaignId, ['701'])) problems.push('campaignId');
  if (!p.meeting || Number.isNaN(Date.parse(p.meeting.startUtc))) problems.push('meeting.startUtc');
  if (!p.options || typeof p.options !== 'object') p.options = {};

  // Lead handling. A payload without a mode comes from an app version before lead modes.
  if (p.mode === undefined || p.mode === null) p.mode = 'create';
  if (!MODES.includes(p.mode)) problems.push('mode');
  if (p.isReschedule != null && typeof p.isReschedule !== 'boolean') problems.push('isReschedule');
  p.isReschedule = p.isReschedule === true;
  if (!optText(p.noteText, 5000)) problems.push('noteText');
  if (!optText(p.sourceLabel, 255)) problems.push('sourceLabel');
  if (!optText(p.mobilePhone, 40)) problems.push('mobilePhone');
  if (!optText(p.isoName, 255)) problems.push('isoName');
  if (p.mode !== 'create') {
    // Matching needs the invitee's email; the Meeting Booked writer needs the rep's email.
    if (!lead || !EMAIL.test(String(lead.Email || '').trim())) problems.push('lead.Email');
    if (!p.meeting || !EMAIL.test(String(p.meeting.hostEmail || '').trim())) problems.push('meeting.hostEmail');
  }
}
if (problems.length) return reject(422, 'invalid payload: ' + [...new Set(problems)].join(', '));

// SOQL string escaping, the same as the Calendly lead flow: backslash first, then quote.
const esc = s => String(s || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const inviteeEmail = p.mode === 'create' ? null : String(p.lead.Email).trim().toLowerCase();
return [{ json: {
  ok: true,
  bookingId: p.bookingId,
  redisKey: 'btc-scheduler:lead:' + p.bookingId,
  ownerEmailEsc: p.owner.mode === 'assigned_host' ? esc(p.owner.ownerEmail) : null,
  inviteeEmail,
  inviteeEmailEsc: inviteeEmail === null ? null : esc(inviteeEmail),
  sf_base: 'https://bigthink.my.salesforce.com/services/data/v60.0',
  payload: p
} }];

// A result for this booking is already stored: answer without touching Salesforce.
// Stored statuses: created (answered as existing), updated and duplicate.
const raw = $input.first().json.cached;
let c = null;
try { c = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { c = null; }
if (!c || !c.status) {
  return [{ json: { httpCode: 422, response: {
    status: 'error', leadId: null, error: 'unreadable idempotency record in Redis', retryable: false, problems: []
  } } }];
}
const duplicate = c.status === 'duplicate';
return [{ json: { httpCode: 200, response: {
  status: duplicate ? 'duplicate' : c.status === 'updated' ? 'updated' : 'existing',
  leadId: c.leadId || null,
  matchedRecordId: c.matchedRecordId || null,
  error: duplicate ? (c.error || 'duplicate') : null,
  retryable: false,
  problems: []
} } }];

// Builds the Lead insert body: payload fields, the resolved owner, and (optionally) the
// Meeting Booked status fields that the shared Calendly writer sets.
const v = $('Verify Signature').first().json;
const p = v.payload;
const problems = [];
const lead = { ...p.lead };
let ownerId = null;

if (p.owner.mode === 'fixed') ownerId = p.owner.ownerId;
if (p.owner.mode === 'assigned_host') {
  let r = null;
  try { r = $('Resolve Owner').first().json; } catch (e) { r = null; }
  const rec = r && Array.isArray(r.records) ? r.records[0] : null;
  if (rec && rec.Id) ownerId = rec.Id;
  else if (r && r.error) problems.push('Owner lookup failed; Lead created with the default owner');
  else problems.push('Assigned host is not an active Salesforce user; Lead created with the default owner');
}
if (ownerId) lead.OwnerId = ownerId;

if (p.options.setMeetingBookedFields === true) {
  Object.assign(lead, {
    Status: 'Working - Contacted',
    csbs__Status_Detail__c: 'Meeting Booked',
    Meeting_booked_time__c: p.meeting.startUtc,
    Meeting_Booked__c: true,
    Do_Not_Contact__c: false
  });
}

return [{ json: {
  sf_base: v.sf_base,
  lead,
  ownerId,
  // Always sent. TRUE only in assignment_rules mode; FALSE otherwise so that Lead
  // assignment rules never re-route a Lead whose owner the app already chose.
  autoAssignHeader: p.autoAssign === true ? 'TRUE' : 'FALSE',
  problems
} }];

// Classifies the Lead insert response into the response contract.
// Duplicate sources in this org:
//   * Standard duplicate rules: errorCode DUPLICATES_DETECTED with duplicateResult.matchResults.
//   * DuplicateCheckHandler (LeadDuplicateTrigger, before insert): addError() surfaces as
//     FIELD_CUSTOM_VALIDATION_EXCEPTION with "Duplicate <reason> detected ..." or the
//     "active Opportunities" warning. Both messages link to the matched record Id.
// Messages are reduced to a reason so record names and owner names are not passed back.
const r = $input.first().json;
const build = $('Build Lead Body').first().json;
const code = Number(r.statusCode || 0);
const body = r.body;
const errs = Array.isArray(body) ? body : (body && body.errorCode ? [body] : []);
const ID = /\b(?:00Q|001|003|006)[A-Za-z0-9]{12}(?:[A-Za-z0-9]{3})?\b/g;
const RETRYABLE = ['UNABLE_TO_LOCK_ROW', 'REQUEST_LIMIT_EXCEEDED', 'SERVER_UNAVAILABLE', 'INVALID_SESSION_ID'];
let out;

if (code >= 200 && code < 300 && body && body.id) {
  out = { status: 'created', leadId: body.id, matchedRecordId: null, error: null, retryable: false };
} else if (!code) {
  // No HTTP response (timeout or network error). The insert may or may not have happened;
  // a retry is then caught by duplicate detection on the invitee's email.
  const e = r.error;
  const msg = (e && (e.message || e.description || (typeof e === 'string' ? e : ''))) || r.message || 'no response';
  out = { status: 'error', leadId: null, matchedRecordId: null, error: 'Salesforce request failed: ' + String(msg).slice(0, 300), retryable: true };
} else {
  const ruleDup = errs.find(e => e.errorCode === 'DUPLICATES_DETECTED');
  const apexDup = errs.find(e => /duplicate/i.test(String(e.message || '')));
  if (ruleDup || apexDup) {
    let ids = [];
    let reason;
    if (ruleDup) {
      const dr = ruleDup.duplicateResult || {};
      for (const m of (dr.matchResults || [])) {
        for (const rec of (m.matchRecords || [])) if (rec.record && rec.record.Id) ids.push(rec.record.Id);
      }
      reason = 'Duplicate rule matched' + (dr.duplicateRule ? ' (' + dr.duplicateRule + ')' : '');
    } else {
      const msg = String(apexDup.message || '');
      ids = msg.match(ID) || [];
      const m = msg.match(/Duplicate (\w+) detected\. This record matches existing (\w+)/);
      reason = m ? 'Duplicate ' + m[1] + ' detected; matches an existing ' + m[2]
        : /active Opportunities/i.test(msg) ? 'Possible duplicate: active Opportunity for this merchant'
        : 'Duplicate check rejected the Lead';
    }
    out = {
      status: 'duplicate',
      leadId: ids.find(i => i.startsWith('00Q')) || null,
      matchedRecordId: ids[0] || null,
      error: reason,
      retryable: false
    };
  } else {
    const first = errs[0] || {};
    const errorCode = first.errorCode || ('HTTP_' + code);
    out = {
      status: 'error', leadId: null, matchedRecordId: null,
      error: (errorCode + ': ' + String(first.message || r.statusMessage || '')).slice(0, 500),
      retryable: code >= 500 || code === 429 || RETRYABLE.includes(errorCode)
    };
  }
}
return [{ json: { ...out, problems: build.problems || [] } }];

// Same note format as the shared Calendly writer. Salesforce rejects ContentNote bodies
// that are not valid HTML, so & < > " are escaped.
const p = $('Verify Signature').first().json.payload;
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const when = new Date(p.meeting.startUtc).toLocaleString('en-US', {
  timeZone: 'America/New_York', weekday: 'short', month: '2-digit', day: '2-digit',
  year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true
});
const lines = [
  '<b>Meeting Booked</b>',
  'Time: ' + esc(when) + ' ET',
  'Agent: ' + esc(p.meeting.hostName || p.meeting.hostEmail || 'Unassigned'),
  'Source: BTC Scheduler - ' + esc(p.meeting.eventTypeName)
];
return [{ json: {
  Title: 'Meeting Booked',
  Content: Buffer.from(lines.join('<br>'), 'utf8').toString('base64')
} }];

// Inspects every Salesforce and Redis write and builds the response. Follow-up failures do
// not change the status (the Lead exists) but are always reported in problems[].
const p = $('Verify Signature').first().json.payload;
const ran = n => { try { return $(n).first().json; } catch (e) { return null; } };
const ok = r => !!r && !r.error && Number(r.statusCode) >= 200 && Number(r.statusCode) < 300;
const mode = p.mode || 'create';
const d = mode === 'create' ? null : ran('Decide Action');
const lookup = ran('Idempotency Lookup');
const lookupProblem = lookup && lookup.error ? 'Redis idempotency lookup failed; continued without it' : null;

// Result of "Calendly - SF Meeting Booked (shared)". Its problems[] are passed on.
const writer = () => {
  const r = ran('Write Meeting Booked');
  const text = x => String(typeof x === 'string' ? x : JSON.stringify(x)).slice(0, 300);
  if (!r) return { failed: true, retryable: true, error: 'Meeting Booked writer did not run' };
  if (r.error) return { failed: true, retryable: true, error: 'Meeting Booked writer failed: ' + text(r.error.message || r.error) };
  if (r.skipped === true) {
    return { failed: true, retryable: false, error: 'Meeting Booked writer skipped the update' + (r.reason ? ': ' + text(r.reason) : '') };
  }
  if (typeof r.ok !== 'boolean') return { failed: true, retryable: false, error: 'Meeting Booked writer returned an unexpected result' };
  const list = (Array.isArray(r.problems) ? r.problems : []).map(text);
  const add = m => { if (!list.includes(m)) list.push(m); };
  if (r.patch_ok === false) add('Lead update (status and Meeting Booked fields) failed');
  if (r.note_ok === false) add('Note create failed');
  if (r.task_ok === false) add('Task create failed');
  if (r.rep_resolved === false) add('Assigned host is not an active Salesforce user; Lead owner not changed');
  return { failed: false, problems: list };
};

let out;
let problems;
if (d && d.action !== 'create') {
  // An existing Lead was looked up: update, skip or lookup error.
  problems = lookupProblem ? [lookupProblem] : [];
  if (d.action === 'update') {
    const w = writer();
    if (w.failed) {
      out = { status: 'error', leadId: null, matchedRecordId: null, error: w.error, retryable: w.retryable };
    } else {
      out = { status: 'updated', leadId: d.leadId, matchedRecordId: null, error: null, retryable: false };
      problems.push(...w.problems);
      const saved = ran('Remember Update');
      if (!saved || saved.error) problems.push('Redis idempotency record not saved');
    }
  } else if (d.action === 'skip') {
    out = {
      status: 'skipped', leadId: null, matchedRecordId: null,
      matchedConvertedId: d.matchedConvertedId || null, reason: d.reason || null,
      error: null, retryable: false
    };
  } else {
    out = { status: 'error', leadId: null, matchedRecordId: null, error: d.error || 'Lead lookup failed', retryable: d.retryable === true };
  }
} else {
  // A Lead insert was attempted: 'create' mode, or no Lead matched in 'match_or_create' mode.
  const c = $('Classify Lead Response').first().json;
  problems = [...(c.problems || [])];
  if (lookupProblem) problems.push(lookupProblem);

  if (c.status === 'created' || c.status === 'duplicate') {
    const saved = ran('Remember Result');
    if (!saved || saved.error) problems.push('Redis idempotency record not saved');
  }
  if (c.status === 'created') {
    if (p.campaignId && !ok(ran('Add Campaign Member'))) problems.push('Campaign member create failed');
    if (mode === 'create') {
      if (p.options.createNote === true) {
        if (!ok(ran('Create ContentNote'))) problems.push('Note create failed');
        else if (!ok(ran('Link Note To Lead'))) problems.push('Note link failed');
      }
      if (p.options.createTask === true && !ok(ran('Create Task'))) problems.push('Task create failed');
    } else {
      const w = writer();
      if (w.failed) problems.push(w.error);
      else problems.push(...w.problems);
    }
  }
  out = { status: c.status, leadId: c.leadId || null, matchedRecordId: c.matchedRecordId || null, error: c.error || null, retryable: c.retryable };
}

const httpCode = out.status === 'error' ? (out.retryable ? 503 : 422) : 200;
return [{ json: { httpCode, response: {
  ...out,
  retryable: out.status === 'error' ? out.retryable === true : false,
  problems
} } }];

// Applies the rules of the Calendly lead flow to the Find Existing Lead result:
//   effective mode: update for a reschedule, otherwise update for update_only and create
//   for match_or_create.
//   1. An open (IsConverted = false) Lead with the invitee's email: update it (created = false).
//   2. Otherwise a converted Lead: skip ("Existing CONVERTED lead found - not creating a duplicate").
//   3. Otherwise effective mode create: create the Lead (created = true).
//   4. Otherwise skip (update only and no Lead, or a reschedule with no Lead).
// Records are ordered by CreatedDate descending, so the newest open Lead wins.
const p = $('Verify Signature').first().json.payload;
const r = $input.first().json || {};
const code = Number(r.statusCode || 0);
const body = r.body;
const isReschedule = p.isReschedule === true;
const effectiveMode = isReschedule || p.mode === 'update_only' ? 'update' : 'create';
const base = { effective_mode: effectiveMode, is_reschedule: isReschedule };
const RETRYABLE = ['UNABLE_TO_LOCK_ROW', 'REQUEST_LIMIT_EXCEEDED', 'SERVER_UNAVAILABLE', 'INVALID_SESSION_ID'];

if (!(code >= 200 && code < 300) || !body || !Array.isArray(body.records)) {
  const errs = Array.isArray(body) ? body : (body && body.errorCode ? [body] : []);
  const first = errs[0] || {};
  const errorCode = first.errorCode || (code ? 'HTTP_' + code : 'NO_RESPONSE');
  const detail = first.message || (r.error && (r.error.message || r.error)) || r.statusMessage || '';
  return [{ json: { ...base,
    action: 'error',
    error: ('Lead lookup failed: ' + errorCode + (detail ? ': ' + String(detail) : '')).slice(0, 500),
    retryable: !code || code >= 500 || code === 429 || RETRYABLE.includes(errorCode)
  } }];
}

const records = body.records.filter(x => x && typeof x.Id === 'string');
const open = records.find(x => x.IsConverted === false);
const converted = records.find(x => x.IsConverted === true);

if (open) {
  return [{ json: { ...base, action: 'update', created: false, leadId: open.Id, existingIso: open.csbs__ISO__c || '' } }];
}
if (converted) {
  return [{ json: { ...base, action: 'skip', reason: 'converted_lead', matchedConvertedId: converted.Id,
    message: 'Existing CONVERTED lead found - not creating a duplicate' } }];
}
if (effectiveMode === 'create') {
  return [{ json: { ...base, action: 'create', created: true } }];
}
return [{ json: { ...base, action: 'skip',
  reason: isReschedule ? 'reschedule_no_open_lead' : 'no_open_lead',
  matchedConvertedId: null,
  message: isReschedule ? 'Reschedule and no existing lead - nothing to update' : 'Update-only mapping and no existing lead'
} }];

// Maps the BTC Scheduler payload to the input of "Calendly - SF Meeting Booked (shared)"
// (yVjvBOx5E3Zc36rX). The writer requires lead_id, rep_email and start_time. Missing
// values are sent as empty strings, like the Calendly lead flow.
const v = $('Verify Signature').first().json;
const p = v.payload;
const d = $('Decide Action').first().json;
const created = d.action === 'create';
const lead = p.lead || {};
const s = x => (x === null || x === undefined ? '' : String(x).trim());
const leadId = created ? $('Classify Lead Response').first().json.leadId : d.leadId;

return [{ json: {
  lead_id: s(leadId),
  rep_email: s(p.meeting.hostEmail).toLowerCase(),
  rep_name: s(p.meeting.hostName),
  iso_id: s(lead.csbs__ISO__c),
  iso_name: s(p.isoName),
  source_label: s(p.sourceLabel) || 'BTC Scheduler - ' + s(p.meeting.eventTypeName),
  // Only the assigned host owner mode moves the Lead to the rep; fixed and assignment
  // rule owners keep the matched Lead's owner.
  set_owner: p.owner.mode === 'assigned_host',
  start_time: s(p.meeting.startUtc),
  end_time: s(p.meeting.endUtc),
  event_type: s(p.meeting.eventTypeName),
  calendly_uri: 'btc-scheduler:' + p.bookingId,
  invitee_name: [lead.FirstName, lead.LastName].map(s).filter(Boolean).join(' '),
  invitee_email: v.inviteeEmail,
  invitee_phone: s(lead.Phone),
  invitee_company: s(lead.Company) || 'Unknown',
  mobile_phone: s(p.mobilePhone),
  note_text: s(p.noteText),
  write_calendar_event: false,
  unmapped: false,
  effective_mode: d.effective_mode,
  existing_iso: created ? '' : s(d.existingIso),
  is_reschedule: p.isReschedule === true,
  created
} }];
